{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C46"],
      "claim": "Tolfenamic acid, a lipophilic carboxylic acid NSAID, had absolute oral bioavailability of 60% in healthy volunteers, supporting high F for the acidic, lipophilic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "6-MNA, a heteroaromatic carboxylic acid, had mean absolute bioavailability of 38%, supporting F ≥20% for the query's acid/heteroaromatic core.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C39"],
      "claim": "Neotame, an acidic compound with a free carboxylate and aromatic group, was systemically available at 34.4% in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Meperidine, a lipophilic aromatic ester, showed oral bioavailability around 45% in humans despite first-pass metabolism, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C37"],
      "claim": "The active metabolite of nabumetone, a methoxy-substituted lipophilic compound, had 38% absolute bioavailability, supporting high F for the methoxy/diaryl query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Fluoxetine, an aryl ether with a lipophilic aromatic system, had 80% oral bioavailability in humans, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Nifedipine, despite extensive first-pass metabolism, had oral bioavailability around 45%, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Medifoxamine, a diphenylmethoxy-related compound, had absolute bioavailability of 21%, just above the threshold, supporting high F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C40"],
      "claim": "Isradipine had only 19% oral bioavailability in healthy young volunteers, providing contradictory low-F evidence, but its dihydropyridine ester structure and first-pass liability are not representative of the acidic query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The preponderance of highly transferable experimental evidence from acidic/lipophilic drugs (tolfenamic acid, 6-MNA, neotame, nabumetone metabolite) and other orally bioavailable compounds indicates F ≥20%; the only sub-20% analogue, isradipine, is a dihydropyridine ester with a distinct first-pass liability and is outweighed.",
  "evidence_gaps": [
    "No direct pharmacokinetic data for the exact query molecule.",
    "Uncertainty about metabolic stability of the methoxydiphenylmethyl group and its effect on first-pass extraction.",
    "The isradipine low-F evidence creates residual uncertainty, though its structural class differs from the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

